<?php require 'config/app.php';if(logged_in())go_dashboard();$title='Login | DiagnosCare';$basePath='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$email=trim($_POST['email']??'');$password=$_POST['password']??'';$st=$pdo->prepare("SELECT * FROM users WHERE email=? LIMIT 1");$st->execute([$email]);$u=$st->fetch();if($u&&hash_equals($u['password'],hash('sha256',$password))){unset($u['password']);session_regenerate_id(true);$_SESSION['user']=$u;go_dashboard();}else flash('danger','Invalid email or password.');}require 'partials/header.php';?>
<div class="login-card"><div class="card p-4 p-md-5"><div class="text-center mb-4"><div class="feature-icon mx-auto mb-3"><i class="bi bi-shield-lock"></i></div><h3 class="fw-bold">Welcome back</h3><p class="text-muted">Sign in to your DiagnosCare account.</p></div><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label class="form-label">Email</label><input class="form-control mb-3" type="email" name="email" required><label class="form-label">Password</label><input id="password" class="form-control mb-2" type="password" name="password" required><div class="form-check mb-3"><input class="form-check-input" type="checkbox" id="show"><label class="form-check-label" for="show">Show password</label></div><button class="btn btn-primary btn-lg w-100">Sign In</button></form><div class="text-center mt-4"><small class="text-muted">New patient? <a href="register.php">Create an account</a></small></div></div></div><script>document.getElementById('show').addEventListener('change',e=>document.getElementById('password').type=e.target.checked?'text':'password');</script><?php require 'partials/footer.php';?>
